<style>
.ci-page{font-family:Inter,sans-serif;color:#25313C}.ci-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:20px}.ci-title{font-size:23px;font-weight:700;color:#123B5D;margin:0}.ci-sub{font-size:13px;color:#64748B;margin:6px 0 0}.ci-actions{display:flex;gap:9px;flex-wrap:wrap}.ci-btn{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 16px;border:1px solid #CBD5E1;border-radius:9px;background:#fff;color:#334155;text-decoration:none;font-size:13px;font-weight:600;cursor:pointer}.ci-btn.primary{background:#123B5D;color:#fff;border-color:#123B5D}.ci-layout{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:16px}.ci-main,.ci-side{background:#fff;border:1px solid #CBD5E1;border-radius:15px;padding:18px}.ci-side h3,.ci-main h3{font-size:15px;color:#123B5D;margin:0 0 13px}.ci-hero{padding:18px;border-radius:12px;background:linear-gradient(120deg,#123B5D,#176B87);color:#fff;margin-bottom:15px}.ci-hero h2{font-size:18px;margin:0 0 6px}.ci-hero p{font-size:12px;margin:0;opacity:.9}.ci-prompts{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.ci-prompt{border:1px solid #CBD5E1;background:#F8FAFC;border-radius:18px;padding:8px 11px;font-size:11px;color:#334155;cursor:pointer}.ci-compose textarea{width:100%;min-height:115px;border:1px solid #CBD5E1;border-radius:10px;padding:12px;font:13px Inter,sans-serif;resize:vertical}.ci-compose-foot{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:10px}.ci-muted{font-size:12px;color:#64748B}.ci-history a{display:block;padding:10px 0;border-bottom:1px solid #E2E8F0;color:#334155;text-decoration:none;font-size:12px}.ci-history a:last-child{border-bottom:0}.ci-message{padding:13px 14px;border-radius:11px;margin:12px 0;white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.6}.ci-user{background:#EFF6FF;margin-left:8%}.ci-assistant{background:#F8FAFC;margin-right:8%}.ci-result{display:none;margin-top:16px}.ci-error{color:#B91C1C;font-size:12px;margin-top:8px}.ci-loading{display:none;color:#64748B;font-size:12px;margin-top:10px}.ci-stat{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.ci-chip{background:#F1F5F9;border-radius:20px;padding:6px 10px;font-size:11px;color:#475569}@media(max-width:850px){.ci-layout{grid-template-columns:1fr}.ci-head{display:block}.ci-actions{margin-top:12px}}
</style>